\label{sec:KKT-prosumer-matrix}

Condier the prosumer's single-epoch optimization problem of maximizing profit given forecasted prices $(\bar{\mathbf{r}}, \bar{\mathbf{c}})$.  Let the stacked decision vector be $\mathbf{z} \in \mathbb{R}^{5T}$, where $\mathbf{z}^\top = \begin{pmatrix} \mathbf{s}^\top & \mathbf{d}^\top & \mathbf{k}^\top & \mathbf{p}^\top & \mathbf{b}^\top \end{pmatrix}$. The marginal effects of the controls on the objective are given by the vector $\mathbf{c}_{\pi} \in \mathbb{R}^{5T}$, $\mathbf{c}_{\pi}^\top = \begin{pmatrix} \bar{\mathbf{r}}^\top & -\bar{\mathbf{c}}^\top & \mathbf{0}^\top & \mathbf{0}^\top & \mathbf{0}^\top \end{pmatrix}$. The optimization problem in matrix form is:
\begin{align*}
\max_{\mathbf{z}} \quad & \mathbf{c}_{\pi}^\top \mathbf{z}  + \gamma \bar{\Pi}(b_T) \\
\text{s.t.} \quad & \mathbf{A}_{\text{eq}} \mathbf{z} = \mathbf{b}_{\text{eq}} \\
& \mathbf{A}_{\text{ineq}} \mathbf{z} \le \mathbf{b}_{\text{ineq}}
\end{align*}
where $b_T$ is the last element of the $\mathbf{b}$ sub-vector within $\mathbf{z}$. The constraint matrices $\mathbf{A}_{\text{eq}} \in \mathbb{R}^{(2T+1) \times 5T}$, $\mathbf{A}_{\text{ineq}} \in \mathbb{R}^{10T \times 5T}$ and vectors $\mathbf{b}_{\text{eq}} \in \mathbb{R}^{2T+1}$, $\mathbf{b}_{\text{ineq}} \in \mathbb{R}^{10T}$ are defined as:
\[
\mathbf{A}_{\text{eq}} =
\begin{pmatrix}
-\mathbf{I} & \mathbf{I} & -\mathbf{I} & -\mathbf{I} & \mathbf{0} \\  
\mathbf{0}^\top & \mathbf{0}^\top & \mathbf{0}^\top & \mathbf{1}^\top & \mathbf{0}^\top \\ 
\mathbf{0} & \mathbf{0} & -\mathbf{L} & \mathbf{0} & \mathbf{I} 
\end{pmatrix}
\quad
\mathbf{b}_{\text{eq}} =
\begin{pmatrix}
-\boldsymbol{\omega} \\
\alpha^{\text{flex}} + \mathbf{1}^\top \boldsymbol{\alpha}^{\text{base}} \\
b_0 \mathbf{1}
\end{pmatrix}
\]
\[
\mathbf{A}_{\text{ineq}} =
\begin{pmatrix}
-\mathbf{I} & \mathbf{0} & \mathbf{0} & \mathbf{0} & \mathbf{0} \\ 
\mathbf{I} & \mathbf{0} & \mathbf{0} & \mathbf{0} & \mathbf{0} \\  
\mathbf{0} & -\mathbf{I} & \mathbf{0} & \mathbf{0} & \mathbf{0} \\ 
\mathbf{0} & \mathbf{I} & \mathbf{0} & \mathbf{0} & \mathbf{0} \\  
\mathbf{0} & \mathbf{0} & -\mathbf{I} & \mathbf{0} & \mathbf{0} \\ 
\mathbf{0} & \mathbf{0} & \mathbf{I} & \mathbf{0} & \mathbf{0} \\  
\mathbf{0} & \mathbf{0} & \mathbf{0} & -\mathbf{I} & \mathbf{0} \\ 
\mathbf{0} & \mathbf{0} & \mathbf{0} & \mathbf{0} & -\mathbf{I} \\ 
\mathbf{0} & \mathbf{0} & \mathbf{0} & \mathbf{0} & \mathbf{I}     

\end{pmatrix}
\quad
\mathbf{b}_{\text{ineq}} =
\begin{pmatrix}
\mathbf{0} \\
X \mathbf{1} \\
\mathbf{0} \\
X \mathbf{1} \\
K \mathbf{1} \\
K \mathbf{1} \\
-\boldsymbol{\alpha}^{\text{base}} \\
\mathbf{0} \\
B \mathbf{1}
\end{pmatrix}
\]

\paragraph{Lagrangian.}
Let $\boldsymbol{\chi} \in \mathbb{R}^{2T+1}$ be the Lagrange multipliers for the equality constraints, partitioned as $\boldsymbol{\chi} = (\boldsymbol{\theta}^\top, \nu, \boldsymbol{\lambda}^\top)^\top$. Let $\boldsymbol{\phi} \in \mathbb{R}^{9T}$, $\boldsymbol{\phi} \ge \mathbf{0}$ be the multipliers for the inequality constraints, partitioned as $\boldsymbol{\phi} = ((\boldsymbol{\zeta}^s)^\top, (\boldsymbol{\xi}^s)^\top, (\boldsymbol{\zeta}^d)^\top, (\boldsymbol{\xi}^d)^\top, (\boldsymbol{\kappa}^L)^\top, (\boldsymbol{\kappa}^U)^\top, \boldsymbol{\mu}^\top, (\boldsymbol{\iota}^L)^\top, (\boldsymbol{\iota}^U)^\top)^\top$. The Lagrangian is given by:
\[
\mathcal{L}(\mathbf{z}, \boldsymbol{\psi}, \boldsymbol{\phi}) = \left[ \mathbf{c}_{\pi}^\top \mathbf{z} + \gamma \bar{\Pi}(b_T) \right] + \boldsymbol{\chi}^\top (\mathbf{b}_{\text{eq}} - \mathbf{A}_{\text{eq}} \mathbf{z}) + \boldsymbol{\phi}^\top (\mathbf{b}_{\text{ineq}} - \mathbf{A}_{\text{ineq}} \mathbf{z})
\]

\paragraph{KKT Stationarity Condition.}
The gradient of the Lagrangian with respect to the primal variables $\mathbf{z}$ must be zero at the optimum $(\mathbf{z}^*, \boldsymbol{\chi}^*, \boldsymbol{\phi}^*)$. Let $\mathbf{e}_T = (0, \dots, 0, 1)^\top \in \mathbb{R}^T$ select the last element, and define the corresponding selector vector in $\mathbb{R}^{5T}$ as $\mathbf{e}_{5T}^\top = (\mathbf{0}^\top, \mathbf{0}^\top, \mathbf{0}^\top, \mathbf{0}^\top, \mathbf{e}_T^\top)$. Let $\pi^b \in \partial \bar{\Pi}(b_T^*)$ be an element of the supergradient of the continuation value function evaluated at the optimal terminal state $b_T^*$. The stationarity condition $\nabla_{\mathbf{z}} \mathcal{L} = \mathbf{0}$ yields:
\[
\mathbf{c}_{\pi} + \gamma \pi^b \mathbf{e}_{5T} - \mathbf{A}_{\text{eq}}^\top \boldsymbol{\chi}^* - \mathbf{A}_{\text{ineq}}^\top \boldsymbol{\phi}^* = \mathbf{0}
\]
Expanding this matrix equation by substituting the definitions of $\mathbf{A}_{\text{eq}}$, $\mathbf{A}_{\text{ineq}}$, $\boldsymbol{\chi}^* = (\boldsymbol{\theta}^{*\top}, \nu^*, \boldsymbol{\lambda}^{*\top})^\top$, and the partitioned $\boldsymbol{\phi}^*$ gives the first-order conditions for each block of variables:
\begin{align*}
\nabla_{\mathbf{s}} \mathcal{L} &= \bar{\mathbf{r}} + \boldsymbol{\theta}^* - \boldsymbol{\zeta}^{s*} + \boldsymbol{\xi}^{s*} = \mathbf{0} \\
\nabla_{\mathbf{d}} \mathcal{L} &= -\bar{\mathbf{c}} + \boldsymbol{\theta}^* - \boldsymbol{\zeta}^{d*} + \boldsymbol{\xi}^{d*} = \mathbf{0} \\
\nabla_{\mathbf{k}} \mathcal{L} &= \boldsymbol{\theta}^* +  \mathbf{L}^\top \boldsymbol{\lambda}^* - \boldsymbol{\kappa}^{L*} + \boldsymbol{\kappa}^{U*} = \mathbf{0} \\
\nabla_{\mathbf{p}} \mathcal{L} &= \boldsymbol{\theta}^* - \nu^* \mathbf{1} - \boldsymbol{\mu}^* = \mathbf{0} \quad (\text{assuming } \boldsymbol{\zeta}^{p*} = \mathbf{0}) \\
\nabla_{\mathbf{b}} \mathcal{L} &= \gamma \pi^b \mathbf{e}_T - \boldsymbol{\lambda}^* + \boldsymbol{\iota}^{L*} - \boldsymbol{\iota}^{U*} = \mathbf{0}
\end{align*}
These equations define the relationships between the optimal primal variables (implicitly through complementary slackness) and the optimal dual variables (shadow prices). For instance, the condition for $\mathbf{p}$ implies $\boldsymbol{\theta}^* = \nu^*  \mathbf{1} + \boldsymbol{\mu}^*$, equating the marginal value of energy to its marginal value in consumption. Similarly, combining the conditions for $\mathbf{k}$ and $\mathbf{b}$ relates $\boldsymbol{\theta}^*$ to the discounted continuation value and the shadow prices of battery constraints over time. The conditions for $\mathbf{s}$ and $\mathbf{d}$ directly link $\boldsymbol{\theta}^*$ to the market prices, adjusted by the multipliers for binding non-negativity ($\boldsymbol{\zeta}^*$) or grid capacity ($\boldsymbol{\xi}^*$) constraints.


\paragraph{Other KKT Conditions.}
In addition to stationarity, the optimal solution must satisfy:
\begin{itemize}[noitemsep]
    \item \textbf{Primal Feasibility:} $\mathbf{A}_{\text{eq}} \mathbf{z}^* = \mathbf{b}_{\text{eq}}$ and $\mathbf{A}_{\text{ineq}} \mathbf{z}^* \le \mathbf{b}_{\text{ineq}}$.
    \item \textbf{Dual Feasibility:} $\boldsymbol{\phi}^* \ge \mathbf{0}$.
    \item \textbf{Complementary Slackness:} $\boldsymbol{\phi}^{*\top} (\mathbf{b}_{\text{ineq}} - \mathbf{A}_{\text{ineq}} \mathbf{z}^*) = 0$. This implies $\phi_i^* = 0$ for any non-binding inequality constraint $i$.
\end{itemize}
These conditions collectively characterize the optimal primal-dual solution $(\mathbf{z}^*, \boldsymbol{\chi}^*, \boldsymbol{\phi}^*)$ to the prosumer's best-response LP.

\begin{proof}
\textbf{($\Rightarrow$) Anonymity implies the existence of $\Phi$.}
Assume the market mechanism is anonymous. Let $\bm{x}_{-n}$ and $\bm{x}'_{-n}$ be any two allocation vectors for the other prosumers that produce the same multiset, i.e., $\Sigma(\bm{x}_{-n}) = \Sigma(\bm{x}'_{-n})$. By definition, this implies that $\bm{x}'_{-n}$ is a permutation of $\bm{x}_{-n}$, which we denote by $\pi$. The definition of anonymity states that $P_n(x_n, \bm{x}_{-n}) = P_n(x_n, \pi(\bm{x}_{-n}))$, which is equivalent to $P_n(x_n, \bm{x}_{-n}) = P_n(x_n, \bm{x}'_{-n})$. Since the payment $P_n$ is invariant for any vector that generates the same multiset, it must be a function of the multiset itself. Thus, a function $\Phi$ as described exists and is well-defined.

\vspace{\baselineskip}

\noindent\textbf{($\Leftarrow$) The existence of $\Phi$ implies Anonymity.}
Conversely, assume there exists a function $\Phi$ such that $P_n(x_n, \bm{x}_{-n}) = \Phi(x_n, \Sigma(\bm{x}_{-n}))$. Let $\pi$ be any permutation of the other prosumers. A key property of multisets is that they are invariant to permutation, meaning $\Sigma(\bm{x}_{-n}) = \Sigma(\pi(\bm{x}_{-n}))$. This allows the following chain of equalities:
\begin{align*}
P_n(x_n, \pi(\bm{x}_{-n})) &= \Phi(x_n, \Sigma(\pi(\bm{x}_{-n}))) && \text{(by assumption)} \\
&= \Phi(x_n, \Sigma(\bm{x}_{-n})) && \text{(by multiset invariance)} \\
&= P_n(x_n, \bm{x}_{-n}) && \text{(by assumption)}
\end{align*}
The result satisfies the definition of anonymity.
\end{proof}


